// Normalise the inbound turn. Asia/Manila has no DST, so a fixed +08:00 is exact — this is
// the one place "today" is computed, and every downstream date decision uses it.
const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MAX_CHARS = 1200;   // Groq context + a 10k-char paste should not become a booking
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  let text = String(j.text == null ? '' : j.text).trim();
  const tooLong = text.length > MAX_CHARS;
  if (tooLong) text = text.slice(0, MAX_CHARS);
  const blank = text.length === 0;

  const manila = new Date(Date.now() + 8 * 3600 * 1000);   // shift, then read UTC parts
  const today = manila.toISOString().slice(0, 10);
  const nowLocal = manila.toISOString().slice(11, 16);

  const user_key = String(j.user_key || ('unknown:' + (j.chat_id == null ? '0' : j.chat_id)));
  const sep = user_key.indexOf(':');
  out.push({ json: {
    user_key,
    channel: sep > 0 ? user_key.slice(0, sep) : (j.channel || 'unknown'),
    channel_user_id: sep > 0 ? user_key.slice(sep + 1) : user_key,
    chat_id: j.chat_id == null ? null : j.chat_id,
    text,
    // Never embed an empty string: the vector is meaningless and would retrieve arbitrary
    // chunks that the model would then treat as relevant notes.
    embed_text: blank ? 'salon greeting' : text,
    blank, tooLong,
    today, weekday: DAYS[manila.getUTCDay()], now_local: nowLocal,
  } });
}
if (out.length === 0) out.push({ json: { user_key: 'unknown:0', channel: 'unknown', channel_user_id: '0',
  chat_id: null, text: '', embed_text: 'salon greeting', blank: true, tooLong: false,
  today: new Date().toISOString().slice(0,10), weekday: '', now_local: '00:00' } });
return out;

// THE deterministic core. Everything the model said is treated as a suggestion; what
// actually happens is decided here, against the real catalogue and the real database.
