  if (s && typeof s === 'object') return s;
  let text = String(s == null ? '' : s).trim();
  text = text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const a = text.indexOf('{'), b = text.lastIndexOf('}');
  if (a === -1 || b <= a) return null;
  let obj = null;
  try { obj = JSON.parse(text.slice(a, b + 1)); } catch (e) { return null; }
  if (!obj || typeof obj !== 'object') return null;
  // Merge a {params:{...}} wrapper without letting it clobber top-level keys.
  if (obj.params && typeof obj.params === 'object') obj = Object.assign({}, obj.params, obj);
  return obj;
}
const agentOut = $input.first().json || {};
const modelDown = agentOut.error !== undefined;          // provider refused / timed out / 429
const m = modelDown ? null : parseModel(raw);
const modelFailed = !modelDown && m === null;            // replied, but not with usable JSON

const INTENTS = ['book', 'cancel', 'availability', 'kb', 'chitchat'];
let intent = INTENTS.includes(String(m && m.intent)) ? m.intent : 'chitchat';

// --- catalogue mapping: exact, never nearest ---------------------------------------
const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]+/g, '');
const ALIASES = {                       // local shorthand a customer really types
  gupit: 'haircut', pagupit: 'haircut', magpagupit: 'haircut', cut: 'haircut',
  kulay: 'haircolour', color: 'haircolour', colour: 'haircolour', haircolor: 'haircolour',
  rebond: 'rebondreform', rebonding: 'rebondreform',
  blowdry: 'blowdrystyle', blower: 'blowdrystyle',
  manicure: 'manicure', mani: 'manicure', spa: 'hairspa', hairspa: 'hairspa',
