  const cleaned = String(name == null ? '' : name).replace(/\([^)]*\)/g, ' ')
                    .replace(/\bservice\b/gi, ' ').trim();
  const k = norm(cleaned); if (!k) return null;
  const key = ALIASES[k] || k;
  return (ctx.services || []).find(s => norm(s.name) === key || norm(s.id).replace(/^svc/, '') === key)
      || (ctx.services || []).find(s => norm(s.name) === k)
      || null;
}
