  const k = norm(String(name == null ? '' : name).replace(/\([^)]*\)/g, ' ')); if (!k) return null;
  return (ctx.stylists || []).find(s => norm(s.name) === k)
      || (ctx.stylists || []).find(s => norm(s.name).split(' ')[0] === k)
      || (ctx.stylists || []).find(s => norm(s.name).startsWith(k) && k.length >= 3) || null;
}

// --- validation --------------------------------------------------------------------
function validDate(d) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(d || ''))) return null;
  const dt = new Date(d + 'T00:00:00Z');
  if (isNaN(dt.getTime()) || dt.toISOString().slice(0, 10) !== d) return null;   // 2026-02-30
  const days = Math.round((dt - new Date(t.today + 'T00:00:00Z')) / 86400000);
  if (days < 0) return { bad: 'past' };
  if (days > HORIZON_DAYS) return { bad: 'far' };
  return { date: d };
}
// Normalise rather than reject. A model asked for "HH:MM" will still hand back "9:00",
// "2pm", "09:00 AM" or "14.00", and refusing those put the agent in a loop asking for a
// time the customer had already given three times. Parsing is cheap; a loop is not.
function validTime(x) {
  // Find the time inside whatever came back rather than demanding an exact shape. The model
  // returns "09:00", "9:00 in the morning", "2pm", "14:00-14:45" — anchoring the pattern made
  // every one of those an error, and because the bad value is carried forward each turn, the
  // agent then asked for the time forever while the customer kept answering it.
  const s = String(x == null ? '' : x).trim().toLowerCase().replace(/\s+/g, '');
  const m = /(\d{1,2})(?:[:.](\d{2}))?(am|pm)?/.exec(s);
  if (!m) return null;
  let h = Number(m[1]);
  const mi = m[2] ? Number(m[2]) : 0;
  const ap = m[3];
  if (ap === 'am') { if (h === 12) h = 0; }
  else if (ap === 'pm') { if (h !== 12) h += 12; }
  else if (!m[2] && h <= 7) h += 12;        // "book me at 3" in a salon means 15:00
  if (h > 23 || mi > 59) return null;
  return `${String(h).padStart(2, '0')}:${String(mi).padStart(2, '0')}`;
}

// --- the customer's own words decide a confirmation, not the model -----------------
// An injected instruction can make the model emit confirm:true; it cannot make the customer
// type "yes". So the literal message is the gate.
// Tokenised, not phrase-matched: "Opo, sige" and "sige na po" are ordinary ways to say yes,
// and an exact-phrase list can never enumerate them. Every word must be an agreement word or
// a filler, and at least one must carry the actual agreement — so "yes, but make it 3pm" is
// NOT a confirmation (it has words that are neither), which is exactly the point.
const YES_CORE = new Set(['yes','y','yep','yeah','ok','okay','okey','sure','confirm','confirmed',
  'sige','opo','oo','g','tama','proceed','correct','book','go','sya','yun']);
const NO_CORE = new Set(['no','nope','nah','hindi','wag','huwag','ayaw','ayoko','cancel','nevermind','stop']);
const FILLER = new Set(['please','po','na','it','do','that','thanks','thank','you','salamat','lang',
  'ako','sir','maam','ma','am','ito','yan','ok']);
const toks = String(t.text || '').toLowerCase().split(/[^a-z\u00f1]+/).filter(Boolean);
function allFrom(core) {
  return toks.length > 0 && toks.length <= 4
    && toks.some(w => core.has(w))
    && toks.every(w => core.has(w) || FILLER.has(w));
}
const affirmative = allFrom(YES_CORE);
const negative = allFrom(NO_CORE);

// --- assemble the draft -------------------------------------------------------------
const pending = prof.pending_fresh ? (prof.pending_booking || null) : null;
// Cross-check the model against the customer's literal words. Two failure modes this kills:
// the model dropping "haircut" out of a sentence that plainly contains it, and the model
// substituting a real service for one we do not offer ("Brazilian blowout" -> Blow Dry).
// Service and stylist are the two fields where being confidently wrong costs the most.
const words = ' ' + String(t.text || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const PHRASES = {                                 // what a customer actually types -> service id
  'haircut': 'svc_haircut', 'hair cut': 'svc_haircut', 'gupit': 'svc_haircut', 'cut': 'svc_haircut',
  'hair colour': 'svc_color', 'hair color': 'svc_color', 'colour': 'svc_color', 'color': 'svc_color', 'kulay': 'svc_color',
  'rebond': 'svc_rebond', 'rebonding': 'svc_rebond', 'rebond reform': 'svc_rebond',
  'blow dry': 'svc_blowdry', 'blowdry': 'svc_blowdry',
  'manicure': 'svc_manicure', 'mani': 'svc_manicure',
  'hair spa': 'svc_hairspa', 'spa': 'svc_hairspa',
};
const ROOTS = { gupit: 'svc_haircut', kulay: 'svc_color', rebond: 'svc_rebond', kuko: 'svc_manicure' };
function serviceFromText() {
  const hits = new Set();
  for (const [phrase, id] of Object.entries(PHRASES)) if (words.includes(' ' + phrase + ' ')) hits.add(id);
  // affix-tolerant: magpagupit / nagpapagupit / pagupit all carry the root "gupit"
  for (const [root, id] of Object.entries(ROOTS)) if (words.includes(root)) hits.add(id);
  for (const sv of (ctx.services || [])) {
    const n = sv.name.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (words.includes(' ' + n + ' ')) hits.add(sv.id);
