  service_id: (svc && svc.id) || base.service_id || null,
  service_name: (svc && svc.name) || base.service_name || null,
  duration_min: (svc && svc.duration_min) || base.duration_min || null,
  price_php: (svc && svc.price_php) || base.price_php || null,
  // Only carry a stylist forward when the CUSTOMER asked for them. The one the system picked
