  // narrows the search to someone who may not even work that day.
  stylist_id: (sty && sty.id) || (base.stylist_requested ? base.stylist_id : null) || null,
  stylist_name: (sty && sty.name) || (base.stylist_requested ? base.stylist_name : null) || null,
