  stylists: ctx.stylists || [], today: t.today,
  user_key: t.user_key, chat_id: t.chat_id, channel: t.channel, channel_user_id: t.channel_user_id,
  learned_name: nameSaid || (state_name_fallback ? draft.client_name : null),
  learned_phone: phoneOk || (state_phone_fallback ? draft.client_phone : null),
  model_reply: (m && typeof m.reply === 'string') ? m.reply : '',
