const pretty = (localStr, weekday) => `${weekday ? weekday + ' ' : ''}${localStr}`;
function dayName(d) {
  const x = new Date(d + 'T00:00:00Z');
  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][x.getUTCDay()];
}
// The diary runs on a grid anchored at each stylist's opening time, so a request for 16:00
// on a 45-minute service is a real miss, not a bug — name the closest real slot.
function nearSlot(slots, want) {          // the closest slot within 45 minutes, or nothing
  if (!slots.length || !want) return null;
  const mins = (h) => Number(h.slice(0, 2)) * 60 + Number(h.slice(3, 5));
  const w = mins(want);
  const best = slots.slice().sort((a, b) => Math.abs(mins(a.starts_at_local.slice(11)) - w)
                                          - Math.abs(mins(b.starts_at_local.slice(11)) - w))[0];
  return Math.abs(mins(best.starts_at_local.slice(11)) - w) <= 45 ? best : null;
}
function nearest(slots, want) {
  if (!slots.length) return 'nothing';
  const mins = (hhmm) => Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5));
  const w = mins(want);
  const best = slots.slice().sort((a, b) => Math.abs(mins(a.starts_at_local.slice(11)) - w)
                                          - Math.abs(mins(b.starts_at_local.slice(11)) - w))[0];
  return `${best.starts_at_local.slice(11)} with ${best.stylist_name}`;
}
function listSlots(slots, n) {
  return slots.slice(0, n).map(x => `${x.starts_at_local.slice(11)} with ${x.stylist_name}`).join(', ');
}
// Anything the model wrote is scrubbed of the two things it must never be able to say.
function scrub(text) {
  let out = String(text || '').trim();
  out = out.replace(/\bBK-\d+\b/gi, '').replace(/\b(confirmed|you'?re booked|booking confirmed|all booked)\b/gi, '');
  out = out.replace(/\s{2,}/g, ' ').trim();
  return out;
}

let reply = '';
let save = 'keep';                 // keep | set | clear
let pendingOut = null;

// What the customer is answering matters more than what they appear to be asking about, so
// an outstanding consent question or waitlist offer is read before anything else.
let waitlist = null;        // {action, entry_id} handed to the save step

if (s.tool === 'submit_review') {
  // A complaint is never argued with. No explanation, no "but", no discount offered on the
  // spot — thank them, tell them a person will pick it up, and stop talking.
  if (r1 && r1.ok) {
    reply = r1.data.sentiment === 'complaint'
      ? "Thank you for telling us — I'm sorry it wasn't right. I've passed this straight to the manager and they'll follow up with you."
      : (r1.data.sentiment === 'praise'
         ? `Thank you! I've passed that on to ${r1.data.stylist_name} and the manager — it means a lot.`
         : 'Thank you for the feedback, it helps us get better.');
    save = 'clear';
  } else if (r1 && r1.reason === 'already_reviewed') {
    reply = 'Thanks — we already have your feedback for that visit on file.'; save = 'clear';
  } else {
    reply = "Thanks for that. I couldn't record it just now, but I've made a note to follow up.";
    save = 'clear';
  }
}
else if (s.tool === 'create_booking' && r1 && s.intent !== 'book' && s.intent !== 'availability') {
  // Confirmed out of the blue (a waitlist offer): the reply is rendered from the tool result
  // here too, so the customer never gets small talk in place of their booking.
  if (r1.ok) { const b = r1.data;
    reply = `Lovely — that's yours: ${b.service_name} with ${b.stylist_name} on ${b.starts_at_local}, `
          + `${money(b.price_php)}. Your reference is ${b.ref}. See you then!`;
    save = 'clear';
    if (s.pending && s.pending.waitlist_entry_id) waitlist = { action: 'accept', entry_id: s.pending.waitlist_entry_id };
  } else {
    reply = r1.reason === 'slot_taken'
      ? "Sorry — someone got to that one first. Shall I keep you on the list for the next opening?"
      : "I couldn't put that through just now, and nothing has been booked. Shall I try again?";
    save = 'clear';
    if (s.pending && s.pending.waitlist_entry_id) waitlist = { action: 'reset', entry_id: s.pending.waitlist_entry_id };
  }
}
else if (s.consent && (s.affirmative || s.negative)) {
  const k = s.consent;
  if (s.negative) {
    reply = `Understood — I'll keep ${k.from_stylist_name} on your ${k.service_name} for ${k.starts_at_local}. `
          + `They may still not make it, so would you like me to find you another time with them, or cancel? `
          + `A manager has been told either way.`;
    save = 'clear';
    waitlist = { action: 'flag_manager', ref: k.ref };
  } else if (r1 && r1.ok) {
    reply = `Done — ${r1.data.service_name} on ${r1.data.starts_at_local} is now with ${r1.data.stylist_name}. `
          + `Same time, same price, and you're in good hands. Ref ${r1.data.ref}.`;
    save = 'clear';
  } else if (r1 && r1.reason === 'replacement_busy') {
    reply = `Sorry — ${k.to_stylist_name} got booked while we were talking. Shall I look for another time, `
          + `or cancel this one? A manager has been told.`;
    save = 'clear';
    waitlist = { action: 'flag_manager', ref: k.ref };
  } else if (r1 && r1.reason === 'already_started') {
    reply = `That appointment has already started, so I've left it as it is.`;
    save = 'clear';
  } else {
    reply = `I couldn't move that one just now, so nothing has changed. A manager has been told.`;
    save = 'clear';
    waitlist = { action: 'flag_manager', ref: k.ref };
  }
}
else if (s.joinAsk && (s.affirmative || s.negative)) {
  if (s.negative) { reply = 'No problem — nothing booked. Anything else I can help with?'; save = 'clear'; }
  else {
    reply = `You're on the list for ${s.joinAsk.service_name} on ${s.joinAsk.date}. `
          + `If anything frees up that day I'll message you straight away — first to reply gets it.`;
    save = 'clear';
    waitlist = { action: 'join', payload: s.joinAsk };
  }
}
else if (s.reviewAsk && s.intent === 'book') {
  // They answered the review request with something else entirely. Drop the ask rather than
  // making them re-answer a question they have moved past; it will not be asked again.
  save = 'clear';
  reply = `No problem — we can come back to the feedback another time. What would you like to book?`;
}
else if (s.blank)       reply = "Sorry, I didn't catch that — what can I do for you?";
else if (s.tooLong)     reply = "That's a lot to read! Could you send me the short version — what you'd like and when?";
else if (s.modelDown)   reply = "Sorry — I'm getting a lot of messages right now. Give me a moment and send that again?";
else if (s.modelFailed) reply = "Sorry, I got my wires crossed there. Could you say that again?";
else if (s.negative && s.pending) {
  reply = 'No problem, I left it as it was. Anything else I can do?';
  save = 'clear';
  // A declined offer is not a consumed one — the slot goes back for the next person.
  if (s.pending.waitlist_entry_id) waitlist = { action: 'reset', entry_id: s.pending.waitlist_entry_id };
}
else if (s.intent === 'kb' || s.intent === 'chitchat') {
  const scrubbed = scrub(s.model_reply);
  if (s.kbDown && s.intent === 'kb') reply = "I'm having trouble looking that up right now — could you try again in a moment?";
  // Not one salon note came back above the floor. Measured on this knowledge base, that means
  // the question is not about the salon at all: greetings and real questions retrieve four to
  // thirteen notes, "what is the capital of France" retrieves zero. So the model has no
  // grounding for whatever it wrote, and prose with no grounding is exactly what must not
  // reach a customer — a rule in the prompt asking it not to answer wore off as the prompt
  // grew, which is why this is code.
  else if (s.kbCount === 0) reply = "That's not something I can help with, I'm afraid — I'm the front desk at Studio Kalye. Can I book you in, or answer something about the salon?";
  else if (scrubbed) reply = scrubbed;
  // A 3B model often leaves `reply` as the empty string it was shown in the template. Small
  // talk is ours to write anyway — only a KB answer has to come from the model.
  else if (s.intent === 'chitchat') reply = "Hello! I'm the front desk at Studio Kalye. I can book you in, move an appointment, or answer questions about the salon — what can I do for you?";
  else reply = "I don't have that detail to hand, but I can have someone from the salon follow up. What else can I help with?";
}
else if (s.intent === 'cancel') {
  if (s.tool === 'cancel_booking' && r1) {
    if (r1.ok) { const f = r1.data.freed;
      reply = `Done — your ${f.service_name} on ${f.starts_at_local} is cancelled. Nothing's charged. Shall I look for another time?`;
      save = 'clear';
    } else if (r1.reason === 'already_cancelled') { reply = 'That one was already cancelled — nothing more to do.'; save = 'clear'; }
    else { reply = "I couldn't cancel that one, sorry. Could you give me the reference again?"; save = 'clear'; }
  } else if (s.booking_ref_said && !s.cancel_target) {
    reply = "I can't find that booking under this chat. Could you double-check the reference?";
  } else if (s.upcoming.length === 0) {
    reply = "You don't have anything booked with us at the moment. Want me to find you a slot?";
  } else if (s.cancel_target) {
    const a = s.cancel_target;
    reply = `Just to be sure — cancel your ${a.service} with ${a.stylist} on ${pretty(a.starts_at_local, a.weekday)}? Reply yes and I'll take care of it.`;
    save = 'set'; pendingOut = { kind: 'cancel', ref: a.ref, summary: `cancel ${a.ref} ${a.service} ${a.starts_at_local}` };
  } else {
    reply = 'You have a few coming up — which one shall I cancel?\n' +
      s.upcoming.map(a => `• ${a.ref} — ${a.service} with ${a.stylist}, ${pretty(a.starts_at_local, a.weekday)}`).join('\n');
  }
}
else if (s.intent === 'book' || s.intent === 'availability') {
  const d = s.draft;
  // Same service, same moment, already on their card: matched once, before any read-back or
  // create, so the answer is "you already have it" and never "someone else took it".
  const dup = (s.intent === 'book' && d.date && d.time)
    ? s.upcoming.find(a => a.service_id === d.service_id && a.starts_at_local === `${d.date} ${d.time}`)
    : null;
  // A "yes" with nothing waiting on it is not a confirmation of anything. Rebuilding a
  // booking out of the chat window here is how a stale affirmative turns into a real
  // appointment twenty turns after the customer stopped paying attention.
  if (s.affirmative && !s.pending && s.intent === 'book') {
    reply = "I don't have anything waiting for your go-ahead. What would you like to book?";
  }
  else if (s.tool === 'create_booking' && r1) {
    if (r1.ok) { const b = r1.data;
      reply = `You're all set${b.idempotent_replay ? ' (already had this one down for you)' : ''} — ${b.service_name} with ${b.stylist_name} on ${b.starts_at_local}, ${money(b.price_php)}. Your reference is ${b.ref}. See you then!`;
      save = 'clear';
      // They took a slot they were waiting for: close the waitlist entry too.
      if (s.pending && s.pending.waitlist_entry_id) waitlist = { action: 'accept', entry_id: s.pending.waitlist_entry_id };
    } else if (r1.reason === 'slot_taken') {
      const slots = (alt && alt.ok) ? alt.data.slots : [];
      reply = slots.length
        ? `Ah — someone just took that slot. Still free that day: ${listSlots(slots, 3)}. Want any of those?`
        : "Ah — someone just took that slot, and there's nothing else free that day. Shall I look at another day?";
      save = 'clear';
      // An offer that lost the race goes back in the queue rather than being consumed.
      if (s.pending && s.pending.waitlist_entry_id) waitlist = { action: 'reset', entry_id: s.pending.waitlist_entry_id };
    } else {
      reply = 'Something went wrong putting that through, and nothing was booked. Could you try again in a moment?';
      save = 'clear';
    }
  }
  else if (dup) {
    reply = `You already have that one — ${dup.ref}, ${dup.service} with ${dup.stylist} on ${pretty(dup.starts_at_local, dup.weekday)}. Want me to move it or book something else?`;
  }
  else if (s.dateBad === 'past') reply = `That date has already passed — today is ${s.today}. What day works for you?`;
  else if (s.dateBad === 'far')  reply = "We only take bookings about three months ahead. Could you pick a nearer date?";
  else if (s.timeBad)            reply = "I didn't catch a valid time — what time were you thinking? (for example 14:00)";
  else if (s.serviceUnknown)     reply = `We don't do that one, sorry. We offer: ${s.services.map(x => x.name).join(', ')}. Which would you like?`;
  else if (s.stylistUnknown)     reply = `I don't have a stylist by that name. Ours are ${s.stylists.map(x => x.name).join(', ')} — or I can book whoever's free.`;
  else if (s.phoneBad)           reply = "That doesn't look like a contact number — what's the best number to reach you on?";
  else if (!d.service_id)        reply = `What would you like done? We offer: ${s.services.map(x => `${x.name} (${money(x.price_php)})`).join(', ')}.`;
  else if (!d.date)              reply = `Lovely — a ${d.service_name}. What day suits you?`;
  else if (s.tool === 'find_availability' && r1) {
    if (!r1.ok) reply = "I couldn't check the diary just then. Could you try again in a moment?";
    else {
      const slots = r1.data.slots || [];
      const wanted = d.time ? slots.find(x => x.starts_at_local.slice(11) === d.time
                      && (!d.stylist_id || x.stylist_id === d.stylist_id)) : null;
      if (s.intent === 'availability' || !d.time) {
        if (slots.length) {
          reply = `On ${dayName(d.date)} ${d.date} I have: ${listSlots(slots, 5)}. Which suits you?`;
        } else {
          // Fully booked is the one moment a waitlist is worth anything. Ask; never add
          // someone silently.
          reply = `We're fully booked for ${d.service_name} on ${dayName(d.date)} ${d.date}. `
                + `Shall I put you on the list for that day? If anything frees up I'll message you first. `
                + `Reply yes, or tell me another day.`;
          save = 'set';
          pendingOut = { kind: 'waitlist_join', service_id: d.service_id, service_name: d.service_name,
                         date: d.date, preferred_stylist_id: d.stylist_id || null,
                         client_name: d.client_name, client_phone: d.client_phone,
                         summary: `waitlist ${d.service_name} ${d.date}` };
        }
      } else if (!wanted && nearSlot(slots, d.time) && d.client_name && d.client_phone) {
        // The diary runs on a grid, so most natural times ("2pm") are a near-miss rather than
        // a refusal. Offer the closest real slot explicitly and let them say yes to THAT.
        const n = nearSlot(slots, d.time);
        const key = `${s.user_key}:${Date.now()}`;
        pendingOut = { kind: 'book', booking_key: key,
          service_id: d.service_id, service_name: d.service_name, duration_min: d.duration_min,
          price_php: d.price_php, stylist_id: n.stylist_id, stylist_name: n.stylist_name,
          date: d.date, time: n.starts_at_local.slice(11), starts_at_utc: n.starts_at_utc,
          stylist_requested: !!d.stylist_id,
          starts_at_local: n.starts_at_local, weekday: dayName(d.date),
          client_name: d.client_name, client_phone: d.client_phone,
          summary: `${d.service_name} with ${n.stylist_name} on ${dayName(d.date)} ${n.starts_at_local}` };
        save = 'set';
        reply = `I don't have ${d.time} that day — the closest is ${n.starts_at_local.slice(11)} with ${n.stylist_name}.\n`
              + `• ${d.service_name} (${d.duration_min} min, ${money(d.price_php)})\n`
              + `• ${dayName(d.date)} ${d.date} at ${n.starts_at_local.slice(11)} (Manila time)\n`
              + `• With ${n.stylist_name}\n• Under ${d.client_name}, ${d.client_phone}\n`
              + `Shall I book that instead? Reply yes to confirm.`;
      } else if (!wanted) {
        reply = slots.length
          ? `${d.time} isn't free${d.stylist_name ? ' with ' + d.stylist_name : ''} that day — the nearest I have is ${nearest(slots, d.time)}. I also have ${listSlots(slots, 3)}. Any of those work?`
          : `We're fully booked on ${dayName(d.date)} ${d.date}. Shall I look at another day?`;
      } else if (!d.client_name) reply = "Happy to hold that for you — what name shall I put it under?";
      else if (!d.client_phone)  reply = `Thanks ${d.client_name} — and the best contact number for you?`;
      else {
        // Everything is known AND the slot is genuinely free: read it back and remember
        // exactly what we offered. The "yes" that follows books THIS, nothing else.
        const key = `${s.user_key}:${Date.now()}`;
        pendingOut = { kind: 'book', booking_key: key,
          service_id: d.service_id, service_name: d.service_name, duration_min: d.duration_min,
          price_php: d.price_php, stylist_id: wanted.stylist_id, stylist_name: wanted.stylist_name,
          date: d.date, time: d.time, starts_at_utc: wanted.starts_at_utc,
          stylist_requested: !!d.stylist_id,
          starts_at_local: wanted.starts_at_local, weekday: dayName(d.date),
          client_name: d.client_name, client_phone: d.client_phone,
          summary: `${d.service_name} with ${wanted.stylist_name} on ${dayName(d.date)} ${wanted.starts_at_local}` };
        save = 'set';
        reply = `Here's what I have:\n• ${d.service_name} (${d.duration_min} min, ${money(d.price_php)})\n`
              + `• ${dayName(d.date)} ${d.date} at ${d.time} (Manila time)\n`
              + `• With ${wanted.stylist_name}\n• Under ${d.client_name}, ${d.client_phone}\n`
              + `Shall I book it? Reply yes to confirm.`;
      }
    }
  }
  else if (!d.client_name)  reply = "Happy to sort that out — what name shall I put it under?";
  else if (!d.client_phone) reply = `Thanks ${d.client_name} — and the best contact number for you?`;
  else reply = "What would you like to book, and when?";
}
if (!reply) reply = "Sorry, could you say that again?";

// Nothing to confirm yet, but a booking is under way: remember what we have so the next
// turn resumes here even if the model drops the thread entirely.
if (save === 'keep' && (s.intent === 'book' || s.intent === 'availability')
    && !s.modelDown && !s.modelFailed) {
  const d2 = s.draft;
  if (d2.service_id || d2.date) {
    save = 'set';
    pendingOut = { kind: 'draft', service_id: d2.service_id, service_name: d2.service_name,
      duration_min: d2.duration_min, price_php: d2.price_php,
      stylist_id: d2.stylist_id, stylist_name: d2.stylist_name, stylist_requested: !!d2.stylist_id,
      date: d2.date, time: d2.time, client_name: d2.client_name, client_phone: d2.client_phone,
      summary: 'in progress' };
  }
}

const wlJoin = waitlist && waitlist.action === 'join'
  ? Object.assign({}, waitlist.payload,
      { client_name: s.draft.client_name, client_phone: s.draft.client_phone })
  : (waitlist && waitlist.action === 'flag_manager'
      ? { appointment_id: (s.consent || {}).appointment_id, summary: `unresolved decline on ${waitlist.ref}` }
      : null);

return [{ json: {
  reply,
  user_key: s.user_key, chat_id: s.chat_id,
  channel: s.channel, channel_user_id: s.channel_user_id,
  save_mode: save,
  learned_name: s.learned_name, learned_phone: s.learned_phone,
  pending_json: pendingOut ? JSON.stringify(pendingOut) : null,
  wl_action: waitlist ? waitlist.action : null,
  wl_entry: (waitlist && waitlist.entry_id) || null,
  wl_json: wlJoin ? JSON.stringify(wlJoin) : null,
} }];

// What the channel adapter sends back to the customer.
const r = $('Render reply').first().json;
return [{ json: { reply: r.reply, user_key: r.user_key, chat_id: r.chat_id } }];
